// ── Transform Data (FINAL WORKING VERSION) ───────────

// STEP 1: Original lead
const lead = $('Prepare Lead').item.json;

// STEP 2: Clearbit for domain
const clearbitRaw = $('HTTP Request - Clearbit').item.json;
let clearbitResults = [];
if (Array.isArray(clearbitRaw)) clearbitResults = clearbitRaw;
else if (Array.isArray(clearbitRaw.body)) clearbitResults = clearbitRaw.body;

// STEP 3: Wikipedia response
// extract field has the full description text
const wiki = $('HTTP Request - Wikipedia').item.json;
const extract = wiki?.extract || wiki?.description || '';
const wikiTitle = wiki?.title || '';

// STEP 4: Fuzzy match Clearbit for domain
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const nameNorm = norm(lead.companyName);
const match = clearbitResults.find(r => norm(r.name) === nameNorm)
  || clearbitResults.find(r => norm(r.name).startsWith(nameNorm))
  || clearbitResults[0]
  || null;

// STEP 5: Domain
const cleanD = (d) => (d && d !== 'null' && d !== 'undefined') ? d : '';
const domain = cleanD(match?.domain)
  || cleanD(lead.domain)
  || (norm(lead.companyName) + '.com');




// STEP 6: Extract LOCATION from Wikipedia extract text
let location = '';
const locPatterns = [
  /based in ([A-Z][a-zA-Z\s]+?)(?:,|\.|and|\s+is|\s+was|\s+that)/,
  /headquartered in ([A-Z][a-zA-Z\s]+?)(?:,|\.|and|\s+is|\s+was)/,
  /located in ([A-Z][a-zA-Z\s]+?)(?:,|\.|and|\s+is|\s+was)/,
  /founded in ([A-Z][a-zA-Z\s]+?)(?:,|\.|and|\s+is|\s+was)/,
  /in ([A-Z][a-zA-Z]+),\s*(Bangladesh|India|Pakistan|USA|UK|Singapore|Nigeria)/,
  /([A-Z][a-zA-Z]+),\s*(Bangladesh|India|Pakistan|USA|UK|Singapore|Nigeria)/,
];
const extractText = extract || '';
for (const p of locPatterns) {
  const found = extractText.match(p);
  if (found) {
    location = found[1].trim();
    // Add country if captured in group 2
    if (found[2]) location = `${found[1].trim()}, ${found[2]}`;
    break;
  }
}







// STEP 7: Extract NICHE from Wikipedia extract text
let niche = '';
const nicheMap = [
  { keywords: ['ride-sharing','ridesharing','ride sharing','motorcycle taxi'], label: 'Ride-Sharing Tech' },
  { keywords: ['logistics','courier','last-mile','freight','shipping'],        label: 'Logistics Tech' },
  { keywords: ['food delivery','restaurant','meal'],                           label: 'Food Tech' },
  { keywords: ['e-commerce','ecommerce','online shopping','online store'],     label: 'E-Commerce' },
  { keywords: ['fintech','financial technology','payments','mobile banking'],  label: 'Fintech' },
  { keywords: ['software as a service','saas','cloud software'],               label: 'SaaS' },
  { keywords: ['artificial intelligence','machine learning',' ai '],           label: 'AI Tech' },
  { keywords: ['health','healthcare','telemedicine','medical'],                label: 'Health Tech' },
  { keywords: ['education','edtech','e-learning','online learning'],           label: 'EdTech' },
  { keywords: ['real estate','property','proptech'],                           label: 'PropTech' },
  { keywords: ['travel','tourism','hotel','hospitality'],                      label: 'Travel Tech' },
  { keywords: ['social media','social network','content platform'],            label: 'Social Media' },
  { keywords: ['on-demand','digital platform','super app'],                    label: 'Super App' },
  { keywords: ['cybersecurity','security software','infosec'],                 label: 'Cybersecurity' },
  { keywords: ['marketplace','classifieds','listing'],                         label: 'Marketplace' },
  { keywords: ['technology company','tech company','software company'],        label: 'Tech Company' },

  { 
  keywords: [
    'bank', 'banking', 'commercial bank', 'private bank',
    'state-owned bank', 'central bank', 'financial institution',
    'retail banking', 'corporate banking', 'investment bank',
    'microfinance', 'micro finance', 'loan', 'lending',
    'credit card', 'debit card', 'atm', 'branch banking'
  ],
  label: 'Banking & Financial Services'
},
];
const extractLower = extractText.toLowerCase();
for (const entry of nicheMap) {
  if (entry.keywords.some(kw => extractLower.includes(kw))) {
    niche = entry.label;
    break;
  }
}

// STEP 8: Return clean enriched object
return {
  json: {
    companyName:      wikiTitle || match?.name || lead.companyName,
    website:          `https://${domain}`,
    email:            `info@${domain}`,
    niche:            niche || 'Tech Startup',
    location:         location || 'South Asia',
    wikiSummary:      extractText.slice(0, 150),
    enrichmentStatus: domain ? 'enriched' : 'failed',
  }
};

