// ── Extract + Merge (FIXED) ──────────────────────────

// STEP 1: Get enriched lead from Transform Data node
const lead = $('Transform Data').item.json;

// STEP 2: Get Groq AI response
const raw = $input.item.json;
const content = raw?.choices?.[0]?.message?.content || '';

// STEP 3: Split subject and body
let subject = '';
let body = content;

if (content.includes('Subject:')) {
  const parts = content.split('\n');
  const subjectLine = parts.find(l => l.toLowerCase().startsWith('subject:'));
  subject = subjectLine
    ? subjectLine.replace(/subject:/i, '').trim()
    : '';
  body = parts
    .filter(l => !l.toLowerCase().startsWith('subject:'))
    .join('\n')
    .trim();
}

// STEP 4: Timestamp
const timestamp = new Date().toISOString();

// STEP 5: Return — correct n8n format, no contactName
return {
  json: {
    companyName:  lead.companyName  || '',
    website:      lead.website      || '',
    niche:        lead.niche        || '',
    location:     lead.location     || '',
    email:        lead.email        || '',
    wikiSummary:  lead.wikiSummary  || '',
    emailSubject: subject,
    emailBody:    body,
    status:       content ? 'SUCCESS' : 'FAILED',
    timestamp:    timestamp,
  }
};

// ── Prepare Lead ─────────────────────────────────────
// Reads company name from Google Sheet
// Prepares searchQuery and wikiQuery for both HTTP nodes

const input = $input.item.json;

// Normalize all keys to lowercase to handle any column naming
const n = Object.fromEntries(
  Object.entries(input).map(([k, v]) => [k.toLowerCase().trim(), v])
);

// Raw company name from sheet
const rawCompany = n.company || n.companyname
  || n['company name'] || '';

// Title case for Wikipedia — "brac bank" → "Brac Bank"
const titleCase = rawCompany
  .split(' ')
  .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
  .join(' ');

// Wikipedia needs underscores instead of spaces
const wikiQuery = titleCase.replace(/ /g, '_');

return {
  json: {
    companyName: titleCase,
    searchQuery: rawCompany,   // for Clearbit
    wikiQuery:   wikiQuery,    // for Wikipedia URL
    domain:      n.domain || '',
  }
};

// ── Transform Data (FAILURE PATH ONLY) ──

// STEP 1: Original lead (from previous node)
const lead = $('Prepare Lead').item.json;

// STEP 2: Return clean failure record (NO API usage)
return {
  json: {
    companyName: lead.companyName || 'Unknown',
    website: '',
    email: '',
    niche: 'Unknown',
    location: lead.location || 'Unknown',
    wikiSummary: '',

    // ❌ explicitly failed
    enrichmentStatus: 'failed'
  }
};
